[tool error]
{
  "ok": false,
  "name": "get_design_data",
  "error": {
    "type": "invalid_params",
    "message": "'pcs' is not one of ['alignments', 'curves', 'tangents', 'equations', 'anchors', 'profiles', 'pvis', 'vcs']",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "kind": {
          "enum": [
            "alignments",
            "curves",
            "tangents",
            "equations",
            "anchors",
            "profiles",
            "pvis",
            "vcs"
          ]
        },
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "profile": {
          "type": "string",
          "minLength": 1
        },
        "start": {
          "type": "integer",
          "minimum": 0
        },
        "limit": {
          "type": "integer",
          "minimum": 1,
          "maximum": 500
        }
      },
      "required": [],
      "additionalProperties": false
    },
    "example": {
      "kind": "curves",
      "alignment": "ALIGN-1"
    }
  }
}

